values ('pt-en', '62ffd44b', '401 cards')
on conflict (curso, versao) do nothing;

on conflict (curso, card_id) do update set
  tipo = excluded.tipo, nivel = excluded.nivel, tags = excluded.tags, requer = excluded.requer,
